// Telegram keeps undelivered updates for 24h and hands them out from an offset.
// Static data persists between production runs, so we resume where we left off.
const state = $getWorkflowStaticData('global');
return [{ json: { offset: Number(state.telegramOffset ?? 0) } }];

const state = $getWorkflowStaticData('global');
const res = $input.first()?.json ?? {};

// 409 = another getUpdates call is already open for this bot. Telegram allows only
// one at a time, so just skip this tick quietly instead of logging a red failure.
if (res.error_code === 409) {
  return [];
}

if (res.ok !== true) {
  const why = res.description ?? res.error?.message ?? res.error ?? 'no response from Telegram';
  throw new Error(
    'Could not read Telegram updates (' + why + '). Start n8n with '
    + 'TELEGRAM_BOT_TOKEN=<your token> and N8N_BLOCK_ENV_ACCESS_IN_NODE=false.',
  );
}

const updates = Array.isArray(res.result) ? res.result : [];
if (!updates.length) {
  return [];  // nothing new - the run stops here
}

const nextOffset = Math.max(...updates.map((u) => Number(u.update_id))) + 1;
state.telegramOffset = nextOffset;

// Confirm with Telegram right now, before the slow part (the AI call). Otherwise an
// overlapping poll could pick up the same question and answer it twice.
const token = $env.TELEGRAM_BOT_TOKEN;
if (token) {
  try {
    await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://api.telegram.org/bot' + token + '/getUpdates',
      qs: { offset: nextOffset, limit: 1, timeout: 0 },
      json: true,
    });
  } catch (error) {
    // Confirmation is best-effort; the saved offset above already prevents repeats.
  }
}

return updates.map((update) => ({ json: update }));

const STOPWORDS = new Set(['the','a','an','of','to','in','is','are','and','or','for','on','with','it','this',
  'that','my','i','you','we','do','does','did','be','been','can','how','what','why','when','where','which',
  'who','will','would','should','could','me','your','our','from','by','as','at','if','into','about','there',
  'their','they','them','has','have','had','not','no','yes','please','any','some','also','than','then','so',
  'such','using','use','used','get','got','need','want','know','tell','give','make','made']);

function normalizeText(value) {
  return String(value ?? '')
    .toLowerCase()
    .replace(/[^\p{L}\p{N}\s]/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function keywordsOf(value) {
  return normalizeText(value)
    .split(' ')
    .filter((word) => word.length > 2 && !STOPWORDS.has(word));
}

// Flattens a Telegram update into one predictable object and decides whether the
// message is actually a question the bot should answer.
//
// The bot only answers when it is ADDRESSED: "/ask ...", an @mention, or a reply to
// one of its own messages. Those three are exactly what Telegram delivers to a bot
// whose privacy mode is ON, so this works without touching any BotFather setting.
// If you later disable privacy mode (or make the bot a group admin), set
// ANSWER_ANY_QUESTION to true and it will pick up questions with no prefix at all.
const BOT_USERNAME = 'nexushelper421bot';
const ANSWER_ANY_QUESTION = false;

const COMMAND_PREFIX = /^\/(ask|q|question|help|support)(@[A-Za-z0-9_]+)?\s*/i;
const QUESTION_STARTERS = /^(what|why|how|when|where|who|whom|whose|which|can|could|would|should|do|does|did|is|are|was|were|will|may|might|explain|define|describe|compare|contrast|calculate|solve|find|prove|derive|evaluate|list|state|name|difference|meaning)\b/i;
const MIN_QUESTION_LENGTH = 8;

const results = [];

for (const item of $input.all()) {
  const update = item.json ?? {};
  const msg = update.message ?? update.edited_message ?? update.channel_post ?? {};
  const chat = msg.chat ?? {};
  const from = msg.from ?? {};

  // Telegram sends every photo in several resolutions - keep the largest.
  const photos = Array.isArray(msg.photo) ? msg.photo : [];
  const largest = photos.length
    ? photos.reduce((a, b) => ((b.file_size ?? b.width ?? 0) > (a.file_size ?? a.width ?? 0) ? b : a))
    : null;

  const rawText = String(msg.text ?? msg.caption ?? '').trim();
  const mentionPattern = new RegExp('@' + BOT_USERNAME + '\\b', 'i');

  const isCommand = COMMAND_PREFIX.test(rawText);
  const mentionsBot = mentionPattern.test(rawText);
  const isReplyToBot = Boolean(msg.reply_to_message?.from?.is_bot);

  const question = rawText
    .replace(COMMAND_PREFIX, '')
    .replace(mentionPattern, '')
    .trim();
  const hasPhoto = Boolean(largest);

  // Ignore Telegram/other-bot commands the bot was not asked to handle (/start, /rules...).
  const isForeignCommand = rawText.startsWith('/') && !isCommand;

  const looksLikeQuestion = hasPhoto
    || question.endsWith('?')
    || QUESTION_STARTERS.test(question);

  // Addressed = the bot was spoken to directly. Telegram delivers these three even
  // when privacy mode is on, so they always reach us.
  const addressed = isCommand || mentionsBot || isReplyToBot;

  const shouldProcess = !from.is_bot
    && !isForeignCommand
    && (addressed || (ANSWER_ANY_QUESTION && looksLikeQuestion))
    && (question.length >= MIN_QUESTION_LENGTH || hasPhoto);

  results.push({
    json: {
      updateId: update.update_id ?? null,
      chatId: chat.id ?? null,
      chatType: chat.type ?? 'private',
      chatTitle: chat.title ?? null,
      messageId: msg.message_id ?? null,
      threadId: msg.message_thread_id ?? null,
      userId: from.id ?? null,
      userName: [from.first_name, from.last_name].filter(Boolean).join(' ') || from.username || 'there',
      userHandle: from.username ? '@' + from.username : null,
      rawText,
      question: question || (hasPhoto
        ? 'Read the question in this image and answer it.'
        : ''),
      questionKey: normalizeText(question),
      keywords: keywordsOf(question).join(' '),
      isCommand,
      mentionsBot,
      isReplyToBot,
      addressed,
      hasPhoto,
      hasImage: false,
      imageDataUrl: null,
      fileId: largest ? largest.file_id : null,
      isBot: Boolean(from.is_bot),
      looksLikeQuestion,
      shouldProcess,
      receivedAt: new Date().toISOString(),
    },
  });
}

return results;

// Converts the file downloaded from Telegram into a data URL the vision model accepts,
// and re-attaches the message context (the Telegram file node returns binary only).
const ctx = $('Normalize Message').first().json;
const item = $input.first();
const binaryKeys = Object.keys(item.binary ?? {});

let imageDataUrl = null;
let mimeType = null;
let sizeKb = 0;

if (binaryKeys.length) {
  const key = binaryKeys[0];
  const meta = item.binary[key];
  mimeType = meta.mimeType || 'image/jpeg';

  // meta.data is empty when n8n stores binaries on the filesystem / S3.
  let base64 = meta.data;
  if (!base64) {
    const buffer = await this.helpers.getBinaryDataBuffer(0, key);
    base64 = buffer.toString('base64');
  }

  sizeKb = Math.round(((base64.length * 3) / 4) / 1024);
  imageDataUrl = 'data:' + mimeType + ';base64,' + base64;
}

// NVIDIA NIM only accepts inline base64 below ~180 KB; larger files need the NVCF
// assets API. Rather than fail, fall back to answering from the caption alone.
const tooLarge = sizeKb > 175;

return [{
  json: {
    ...ctx,
    hasImage: Boolean(imageDataUrl) && !tooLarge,
    imageDataUrl: tooLarge ? null : imageDataUrl,
    imageMimeType: mimeType,
    imageSizeKb: sizeKb,
    imageSkippedReason: tooLarge ? 'image_exceeds_inline_base64_limit' : null,
  },
}];

const STOPWORDS = new Set(['the','a','an','of','to','in','is','are','and','or','for','on','with','it','this',
  'that','my','i','you','we','do','does','did','be','been','can','how','what','why','when','where','which',
  'who','will','would','should','could','me','your','our','from','by','as','at','if','into','about','there',
  'their','they','them','has','have','had','not','no','yes','please','any','some','also','than','then','so',
  'such','using','use','used','get','got','need','want','know','tell','give','make','made']);

function normalizeText(value) {
  return String(value ?? '')
    .toLowerCase()
    .replace(/[^\p{L}\p{N}\s]/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function keywordsOf(value) {
  return normalizeText(value)
    .split(' ')
    .filter((word) => word.length > 2 && !STOPWORDS.has(word));
}

// Fuzzy-matches the incoming question against every stored question in the data table.
// Exact normalised match wins outright; otherwise keyword overlap decides.
const MATCH_THRESHOLD = 0.62;
const MIN_SHARED_KEYWORDS = 2;

let ctx = $('Normalize Message').first().json;
try {
  const withImage = $('Attach Image Context').first().json;
  if (withImage) {
    ctx = { ...ctx, ...withImage };
  }
} catch (error) {
  // Text-only message: the image branch never ran, so keep the base context.
}

const askedKey = ctx.questionKey;
const askedWords = new Set(keywordsOf(ctx.question));

function similarity(storedWords) {
  if (!askedWords.size || !storedWords.size) return { score: 0, shared: 0 };
  let shared = 0;
  for (const word of askedWords) {
    if (storedWords.has(word)) shared += 1;
  }
  const union = askedWords.size + storedWords.size - shared;
  const jaccard = shared / union;
  const coverage = shared / Math.min(askedWords.size, storedWords.size);
  return { score: 0.5 * jaccard + 0.5 * coverage, shared };
}

const scored = $input
  .all()
  .map((item) => item.json)
  .filter((row) => row && row.answer && (row.question || row.question_key))
  .map((row) => {
    const storedWords = new Set(
      row.keywords ? String(row.keywords).split(' ').filter(Boolean) : keywordsOf(row.question),
    );
    const exact = Boolean(askedKey) && row.question_key === askedKey;
    const { score, shared } = similarity(storedWords);
    return {
      id: row.id ?? null,
      question: row.question,
      answer: row.answer,
      hits: Number(row.hits ?? 0),
      source: row.source ?? 'ai',
      shared,
      score: exact ? 1 : score,
      exact,
    };
  })
  .sort((a, b) => b.score - a.score);

const best = scored[0] ?? null;

// A photo always goes to the vision model - a stored text answer cannot have seen it.
const kbHit = Boolean(best)
  && !ctx.hasImage
  && (best.exact || (best.score >= MATCH_THRESHOLD && best.shared >= MIN_SHARED_KEYWORDS));

return [{
  json: {
    ...ctx,
    kbHit,
    kbAnswer: kbHit ? best.answer : null,
    kbQuestion: kbHit ? best.question : null,
    kbRowId: kbHit ? best.id : null,
    kbHits: kbHit ? best.hits : 0,
    kbScore: best ? Number(best.score.toFixed(3)) : 0,
    kbRowsSearched: scored.length,
    // Near misses still help the model answer in the community's own words.
    kbCandidates: scored.slice(0, 3).map((c) => ({ question: c.question, answer: c.answer, score: c.score })),
  },
}];

function toTelegramMarkdown(input) {
  let out = String(input ?? '').trim();

  // Telegram's Markdown is not CommonMark: no tables, no ### headings, and bold is a
  // SINGLE asterisk. Models emit all three anyway, so convert rather than strip.
  const lines = out.split('\n');
  const rebuilt = [];
  const cells = (line) => line.trim().replace(/^\||\|$/g, '').split('|').map((c) => c.trim());

  for (let i = 0; i < lines.length; i += 1) {
    const isRow = /^\s*\|.*\|\s*$/.test(lines[i]);
    const isDivider = i + 1 < lines.length && /^\s*\|[\s:|-]+\|\s*$/.test(lines[i + 1]);
    if (isRow && isDivider) {
      const head = cells(lines[i]);
      i += 2;
      while (i < lines.length && /^\s*\|.*\|\s*$/.test(lines[i])) {
        const row = cells(lines[i]);
        rebuilt.push('• ' + row[0]);
        for (let c = 1; c < row.length; c += 1) {
          if (row[c]) rebuilt.push('   ' + (head[c] ? head[c].replace(/\*/g, '') + ': ' : '') + row[c]);
        }
        i += 1;
      }
      i -= 1;
      rebuilt.push('');
    } else {
      rebuilt.push(lines[i]);
    }
  }
  out = rebuilt.join('\n');

  out = out.replace(/^[ \t]{0,3}#{1,6}[ \t]*(.+?)[ \t]*$/gm, (_, h) => '*' + h.replace(/[*_`#]/g, '').trim() + '*');
  // No /s flag: bold never spans paragraphs, and pairing across them corrupts the text.
  out = out.replace(/\*\*\*([^*\n]+?)\*\*\*/g, '*$1*');
  out = out.replace(/\*\*([^*\n]+?)\*\*/g, '*$1*');
  out = out.replace(/__([^_\n]+?)__/g, '_$1_');
  out = out.replace(/\*\*/g, '');  // anything left over is unpaired
  out = out.replace(/^(\s*)[*+-]\s+/gm, '$1• ');
  out = out.replace(/\n{3,}/g, '\n\n');
  return out.trim();
}

function safeMarkdown(input) {
  let out = toTelegramMarkdown(input);
  if (((out.match(/```/g) || []).length) % 2 === 1) out += '\n```';
  for (const ch of ['*', '_']) {
    if ((out.split(ch).length - 1) % 2 === 1) out = out.split(ch).join('');
  }
  if (((out.replace(/```/g, '').match(/`/g) || []).length) % 2 === 1) out = out.replace(/`/g, '');
  return out;
}

const d = $input.first().json;

const timesAsked = Number(d.kbHits ?? 0) + 1;
const footer = '📚 Saved answer from our knowledge base'
  + (timesAsked > 1 ? ' (asked ' + timesAsked + ' times)' : '');

return [{
  json: {
    ...d,
    source: 'kb',
    model: null,
    aiFailed: false,
    answer: safeMarkdown(d.kbAnswer + '\n\n' + footer),
  },
}];

// Builds the OpenAI-compatible request body for the NVIDIA NIM endpoint.
// Nemotron answers text; a vision model takes over when the question is a screenshot.
const TEXT_MODEL = 'nvidia/llama-3.3-nemotron-super-49b-v1';
const VISION_MODEL = 'meta/llama-3.2-90b-vision-instruct';
const MAX_TOKENS = 2048;

const d = $input.first().json;

const reference = (d.kbCandidates ?? [])
  .filter((c) => c.score > 0.25)
  .map((c, i) => '[' + (i + 1) + '] Q: ' + (c.question ?? 'n/a') + '\nA: ' + c.answer)
  .join('\n\n');

const systemPrompt = [
  // Nemotron reasoning toggle - keep it off so replies arrive fast.
  'detailed thinking off',
  '',
  'You are the answer bot for the "' + (d.chatTitle || 'community') + '" Telegram group, where members post',
  'questions and assessment or exam questions and expect a correct, self-contained answer.',
  '',
  'Rules:',
  '- Always answer in English.',
  '- Give the complete answer. A one-line question gets a one-line answer; a problem that needs',
  '  working, steps, or an example gets all of it. Do not pad and do not cut yourself short.',
  '- For an assessment or exam question: state the final answer first, then show the reasoning',
  '  or working underneath so the member can check it.',
  '- For multiple choice: name the correct option and say why the others are wrong.',
  '- If you are genuinely unsure, say so in one line and suggest the member tag a moderator.',
  '  Never guess at a fact and present it as certain.',
  '- Never invent URLs, citations, prices, version numbers, or credentials.',
  '- Telegram formatting only: *single asterisks* for bold, `code`, ``` blocks.',
  '- Never use tables, ### headings, or **double asterisks** - Telegram cannot render them.',
  '',
  reference
    ? 'Previously answered questions from this community - reuse them when they fit:\n' + reference
    : 'No previously answered questions matched this one.',
].join('\n');

const userContent = d.hasImage
  ? [
      { type: 'text', text: d.question },
      { type: 'image_url', image_url: { url: d.imageDataUrl } },
    ]
  : d.question;

const payload = {
  model: d.hasImage ? VISION_MODEL : TEXT_MODEL,
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: userContent },
  ],
  temperature: 0.2,
  top_p: 0.9,
  max_tokens: MAX_TOKENS,
  stream: false,
};

return [{ json: { ...d, payload, model: payload.model } }];

