    if ((out.split(ch).length - 1) % 2 === 1) out = out.split(ch).join('');
  }
  if (((out.replace(/```/g, '').match(/`/g) || []).length) % 2 === 1) out = out.replace(/`/g, '');
  return out;
}

// Drop the request body from the item - it can carry a large base64 image.
const { payload, ...d } = $('Build AI Prompt').first().json;
const res = $input.first()?.json ?? {};

let answer = res?.choices?.[0]?.message?.content ?? '';
if (Array.isArray(answer)) {
  answer = answer.map((part) => part.text ?? '').join('');
}

// Nemotron can emit reasoning traces when "detailed thinking" is on - never ship those.
answer = String(answer).replace(/<think>[\s\S]*?<\/think>/gi, '').trim();

const truncated = res?.choices?.[0]?.finish_reason === 'length';
const aiFailed = answer.length === 0;
if (aiFailed) {
  answer = 'I could not generate an answer right now. A moderator will pick this up shortly. 🙇';
}

return [{
  json: {
    ...d,
    source: 'ai',
    aiFailed,
    truncated,
    apiError: res.error ?? res.detail ?? null,
    usage: res.usage ?? null,
    answer: safeMarkdown(answer),
  },
}];

