// Telegram hard-caps a message at 4096 characters, so a long answer becomes several
// messages split on paragraph -> line -> sentence -> word boundaries, in order.
const MAX_CHARS = 3800;

const d = $input.first().json;

function splitAnswer(text) {
  const chunks = [];
  let rest = String(text ?? '').trim();

  while (rest.length > MAX_CHARS) {
    const window = rest.slice(0, MAX_CHARS);
    let cut = -1;
    for (const marker of ['\n\n', '\n', '. ', ' ']) {
      cut = window.lastIndexOf(marker);
      if (cut > MAX_CHARS * 0.5) {
        cut += marker === '. ' ? 1 : 0;
        break;
      }
      cut = -1;
    }
    if (cut <= 0) cut = MAX_CHARS;
    chunks.push(rest.slice(0, cut).trim());
    rest = rest.slice(cut).trim();
  }
  if (rest.length) chunks.push(rest);
  return chunks.length ? chunks : ['(empty answer)'];
}

const parts = splitAnswer(d.answer);

return parts.map((part, index) => ({
  json: {
    ...d,
    chunk: safeMarkdown(parts.length > 1
      ? part + '\n\n(' + (index + 1) + '/' + parts.length + ')'
      : part),
    chunkIndex: index,
    chunkCount: parts.length,
  },
}));
